// Map the available 48h Timeanddate precipitation signal to simplified IMD rainfall bands.
// IMD's official 24h bands are: light 0.1–15.5 mm, moderate 15.6–64.4 mm,
// heavy 64.5–115.5 mm, very heavy 115.6–204.4 mm and extremely heavy >=204.5 mm.
// Because the city source is a 48h amount, rain48/2 is used only as a 24h-equivalent proxy.
function rainfallBand(w){if(!w)return 'very-light';const timeanddate24=(w.rain48||0)/2;const imd24=Number.isFinite(w.imdDailyActual)?w.imdDailyActual:0;const dailyEq=Math.max(timeanddate24,imd24);if(dailyEq>=204.5)return 'extreme';if(dailyEq>=115.6)return 'very-heavy';if(dailyEq>=64.5)return 'heavy';if(dailyEq>=15.6)return 'moderate';if(dailyEq>=2.5)return 'light';return 'very-light'}
function rainfallBandLabel(b){return ({'very-light':'Very light rain','light':'Light rain','moderate':'Moderate rain','heavy':'Heavy rain','very-heavy':'Very heavy rain','extreme':'Extremely heavy rain'})[b]||'Very light rain'}
function rainfallBandRange(b){return ({'very-light':'Trace–2.4 mm','light':'2.5–15.5 mm','moderate':'15.6–64.4 mm','heavy':'64.5–115.5 mm','very-heavy':'115.6–204.4 mm','extreme':'≥204.5 mm'})[b]||'Trace–2.4 mm'}
function classifyWeather(w){const b=rainfallBand(w);return ['heavy','very-heavy','extreme'].includes(b)?'critical':b==='moderate'?'warning':'safe'}

