// Geographic extent matches the 1,594 × 1,868 India political-map canvas used by the map background.
// State marker reference coordinates are aligned to the Survey of India Political Map of India, English 13th Edition (2026).
const MAP_GEO={west:68.44,east:96.87,north:38.06,south:5.12,ratio:1594/1868};
function project(lat,lon){const w=map.clientWidth,h=map.clientHeight,pad=8,innerH=h-pad*2,imageW=innerH*MAP_GEO.ratio,left=(w-imageW)/2,top=pad;const px=left+((lon-MAP_GEO.west)/(MAP_GEO.east-MAP_GEO.west))*imageW;const py=top+((MAP_GEO.north-lat)/(MAP_GEO.north-MAP_GEO.south))*innerH;return {x:px/w*100,y:py/h*100}}
let imdHumidity={};
function weatherForRegion(name){return stateWeather[name]||null}
function humidityForRegion(r){const city=stateWeather[r.name]?.city;return city&&Number.isFinite(imdHumidity[city])?imdHumidity[city]:(stateWeather[r.name]?.humidity??null)}
function weatherRisk(r){const w=weatherForRegion(r.name);if(!w)return .05;return classifyWeather(w)==='critical'?.90:classifyWeather(w)==='warning'?.42:.08}
let stateForecast={};
function forecastWeather(r,day){
 const w=weatherForRegion(r.name);
 if(day===0)return w?{...w,forecastType:'observed'}:null;
 if(day<0)return w?{...w,rain48:null,pop:null,forecastType:'historical-unavailable',historicalAvailable:false}:null;
 const f=stateForecast[r.name]?.[day];
 if(!f)return w?{...w,rain48:null,pop:null,forecastType:'forecast-unavailable'}:null;
 return {...w,rain48:null,pop:null,forecastType:'imd-forecast',imdForecastSeverity:f.severity,imdForecastDistribution:f.distribution,imdForecastCoverage:f.coverage,imdForecastColor:f.color,imdForecastSubdivisions:f.subdivisions};
}
function forecastActivityClass(w){if(!w)return 'very-light';const s=w.imdForecastSeverity;if(!Number.isFinite(s))return rainfallBand(w);return s>=4?'very-heavy':s===3?'heavy':s===2?'moderate':s===1?'light':'very-light';}
function forecastActivityLabel(w){if(!w)return 'No data';return w.forecastType==='imd-forecast'?`IMD ${w.imdForecastDistribution} • ${w.imdForecastCoverage}% station coverage`:w.forecastType==='historical-unavailable'?'Historical rainfall not available in live feed':rainfallBandLabel(rainfallBand(w));}
function localWaterLevel(r,day){const w=forecastWeather(r,day);if(!w)return 0;const rainfall=w.rain48/48;const runoffFactor=.75+(1-r.elev)*.65;const susceptibility=r.profile?.sus||.5;const drainage=r.drain||.4;const elapsed=Math.max(0,day+2);const accumulated=rainfall*elapsed*24*runoffFactor*(.65+susceptibility*.55);const base=Math.max(0,w.rain48*.008*runoffFactor);return Math.min(2.5,base+accumulated*(1-drainage*.55));}
function modeledWaterLevel(r,day=+($('forecastSlider')?.value||0)){const local=localWaterLevel(r,day);const ns=neighbors(regions.indexOf(r));let inflow=0;ns.forEach(o=>{const n=regions[o.j];const upstream=localWaterLevel(n,day);inflow+=Math.max(0,upstream-local)*.045*(1+(1-r.elev)*.35);});return Math.min(2.5,local+inflow);}
function criticalWaterThreshold(r){return Math.max(.55,1.35-.45*(r.profile?.sus||.5));}
function floodRiskClass(r,day=+($('forecastSlider')?.value||0)){
 const w=forecastWeather(r,day); if(!w)return 'very-low';
 if(w.forecastType==='historical-unavailable'||w.forecastType==='forecast-unavailable')return 'no-data';
 if(w.forecastType==='imd-forecast'){const s=w.imdForecastSeverity||0, sus=r.profile?.sus||.5;const score=s*(.55+.45*sus);return score>=3.35?'very-high':score>=2.55?'high':score>=1.65?'moderate':score>=.75?'low':'very-low';}
 const b=rainfallBand(w);return b==='very-light'?'very-low':b==='light'?'low':b==='moderate'?'moderate':b==='heavy'?'high':'very-high';
}
function floodRiskScore(r,day=+($('forecastSlider')?.value||0)){const x=floodRiskClass(r,day);return x==='no-data'?null:({'very-low':1,low:2,moderate:3,high:4,'very-high':5})[x]||1}
function criticalDay(r){for(let d=0;d<=7;d++){if(['high','very-high'].includes(floodRiskClass(r,d)))return d;}return null;}
function highestRainfallState(day=+($('forecastSlider')?.value||0)){return regions.reduce((best,r)=>{const a=forecastWeather(best,day),b=forecastWeather(r,day);const bw=day>0?(a?.imdForecastSeverity||0):(a?.rain48||0);const rw=day>0?(b?.imdForecastSeverity||0):(b?.rain48||0);return rw>bw?r:best},regions[0]);}
function weatherClass(r,day=+($('forecastSlider')?.value||0)){const risk=floodRiskClass(r,day);return ['high','very-high'].includes(risk)?'critical':risk==='moderate'?'warning':'safe'}
function mapRainClass(r,day=+($('forecastSlider')?.value||0)){const w=forecastWeather(r,day);return day>0?forecastActivityClass(w):rainfallBand(w)}

