function estimatedAffectedPopulation(r,day){const w=forecastWeather(r,day);const population=statePopulationM[r.name]||0;if(!w||!population||day<0)return 0;if(day>0&&w.forecastType==='imd-forecast'){const coverage=Math.min(1,Math.max(0,(Number(w.imdForecastCoverage)||0)/100));const activity=forecastActivityClass(w);const severity={"very-light":0.05,light:0.15,moderate:0.35,heavy:0.6,"very-heavy":0.8,extreme:1}[activity]??0;return population*coverage*severity;}if(!Number.isFinite(w.rain48)&&!Number.isFinite(w.imdDailyActual))return 0;const rain24=Math.max(Number.isFinite(w.imdDailyActual)?w.imdDailyActual:0,Number.isFinite(w.rain48)?w.rain48/2:0);const severity=Math.min(1,Math.max(0,rain24/204.5));return population*severity;}
function totalAffectedPopulation(day){return regions.reduce((sum,r)=>sum+estimatedAffectedPopulation(r,day),0);}
function updateForecastSlider(){const day=+forecastSlider.value;$('forecastDay').textContent=day<0?`${Math.abs(day)} day(s) prior`:day===0?'Today':`Day +${day}`;$('forecastDate').textContent=forecastDateLabel(day);$('forecastNote').textContent=day<0?'No verified historical statewise snapshot is currently available for this date; the dashboard leaves it unfilled rather than inventing rainfall.':day===0?'Showing the latest observed IMD statewise rainfall, with Timeanddate current-weather data where reachable.':`Showing the official IMD 7-day subdivision rainfall forecast for ${day===1?'Day 1':`Day ${day}`}. Future colors represent forecast station coverage/activity, not invented millimetres.`;update();} 
forecastSlider.addEventListener('input',updateForecastSlider);
