function drawChart(){const c=$('chart');if(!c)return;const ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.strokeStyle='#233750';ctx.lineWidth=1;for(let y=0;y<=4;y++){let py=h-35-y*(h-55)/4;ctx.beginPath();ctx.moveTo(45,py);ctx.lineTo(w-15,py);ctx.stroke();ctx.fillStyle='#8ea2b8';ctx.font='11px system-ui';ctx.fillText((y*.4).toFixed(1)+'m',8,py+4)}ctx.strokeStyle='#49b8ff';ctx.lineWidth=3;ctx.beginPath();frames.forEach((f,i)=>{const avg=f.levels.reduce((a,b)=>a+b,0)/f.levels.length,x=45+i*(w-65)/(frames.length-1||1),y=h-35-avg*(h-55)/1.6;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();ctx.strokeStyle='#ff5f6d';ctx.beginPath();frames.forEach((f,i)=>{const max=Math.max(...f.levels),x=45+i*(w-65)/(frames.length-1||1),y=h-35-max*(h-55)/1.6;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();ctx.fillStyle='#8ea2b8';ctx.fillText('Average depth',55,18);ctx.fillText('Peak regional depth',170,18)}
function comparisonStates(){const selectedState=regions[selected];const ranked=regions.filter(r=>r!==selectedState).map(r=>({r,score:Math.max(...Array.from({length:9},(_,k)=>(forecastWeather(r,k-1)?.rain48||0)/2))})).sort((a,b)=>b.score-a.score);return [selectedState,...ranked.slice(0,4).map(x=>x.r)];}
function chartDayFromX(canvas,event,pad){const rect=canvas.getBoundingClientRect(),x=(event.clientX-rect.left)*(canvas.width/rect.width);return Math.max(-1,Math.min(7,Math.round((x-pad.l)/(canvas.width-pad.l-pad.r)*8-1)))}
function chartTooltip(canvas,event,type){const rect=canvas.getBoundingClientRect(),x=(event.clientX-rect.left)*(canvas.width/rect.width),y=(event.clientY-rect.top)*(canvas.height/rect.height),pad=type==='rain'?{l:58,r:18,t:38,b:38}:{l:68,r:18,t:38,b:38};const day=chartDayFromX(canvas,event,pad),series=comparisonStates();let best=null,bestDist=1e9;series.forEach(r=>{const fw=forecastWeather(r,day);const value=type==='rain'?(day>0?(fw?.imdForecastCoverage??null):(fw?.rain48!=null?fw.rain48/2:null)):floodRiskScore(r,day),maxY=type==='rain'?100:5;if(value==null)return;const py=canvas.height-pad.b-(canvas.height-pad.t-pad.b)*(type==='rain'?value/maxY:value/5),px=pad.l+(canvas.width-pad.l-pad.r)*(day+2)/9,d=Math.hypot(x-px,y-py);if(d<bestDist){bestDist=d;best={r,value,px,py}}});if(!best||bestDist>55){$('chartTooltip').style.display='none';return}const w=forecastWeather(best.r,day),band=rainfallBand(w),risk=floodRiskClass(best.r,day);const valueText=type==='rain'?(day>0?(w?forecastActivityLabel(w):'No forecast data'):(w?.rain48!=null?`${(w.rain48/2).toFixed(1)} mm / 24h`:'Historical data unavailable')):({'very-low':'Very Low',low:'Low',moderate:'Moderate',high:'High','very-high':'Very High','no-data':'No verified data'})[risk];const signalText=day>0?(w?forecastActivityLabel(w):'No forecast data'):(w?rainfallBandLabel(band):'Historical data unavailable');$('chartTooltip').innerHTML=`<strong>${best.r.name}${best.r===regions[selected]?' • selected':''}</strong><br><span>${day<0?`${Math.abs(day)} day(s) before today`:day===0?'Today':`Day +${day}`}</span><br><b>${type==='rain'?'Rainfall / forecast signal':'Flood-risk'}: ${valueText}</b><br><span>${signalText}</span>`;$('chartTooltip').style.display='block';$('chartTooltip').style.left=Math.min(event.clientX+14,window.innerWidth-230)+'px';$('chartTooltip').style.top=Math.max(10,event.clientY-75)+'px'}
function drawFloodProgression(){const c=$('floodChart');if(!c)return;const ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);const pad={l:68,r:18,t:38,b:38},labels=['Very Low','Low','Moderate','High','Very High'];ctx.font='11px system-ui';for(let k=0;k<=5;k++){const y=h-pad.b-(h-pad.t-pad.b)*k/5;ctx.strokeStyle='#263c55';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(w-pad.r,y);ctx.stroke();ctx.fillStyle='#8ea2b8';ctx.fillText(k===0?'No rain':labels[k-1],7,y+4)}for(let d=-1;d<=7;d++){const x=pad.l+(w-pad.l-pad.r)*(d+1)/8;ctx.fillStyle='#8ea2b8';ctx.fillText(d<0?`${d}d`:d===0?'Today':`+${d}d`,x-14,h-12)}const series=comparisonStates();series.forEach((r,si)=>{const idx=regions.indexOf(r);ctx.strokeStyle=idx===selected?'#ffffff':`rgba(120,190,230,${.55-si*.07})`;ctx.lineWidth=idx===selected?4:2;ctx.beginPath();let started=false;for(let d=-1;d<=7;d++){const v=floodRiskScore(r,d);if(v==null){started=false;continue;}const x=pad.l+(w-pad.l-pad.r)*(d+1)/8,y=h-pad.b-(h-pad.t-pad.b)*v/5;if(started)ctx.lineTo(x,y);else ctx.moveTo(x,y);started=true}ctx.stroke()});const r=regions[selected],risk=floodRiskClass(r,+forecastSlider.value),riskLabel=({'very-low':'Very Low',low:'Low',moderate:'Moderate',high:'High','very-high':'Very High'})[risk],eta=criticalDay(r);ctx.fillStyle='#fff';ctx.font='bold 12px system-ui';ctx.fillText(`Flood-risk trend • selected: ${r.name}`,pad.l,18);ctx.font='10px system-ui';series.forEach((s,i)=>{ctx.fillStyle=i===0?'#fff':'#7db7d9';ctx.fillText(`${i===0?'● ':''}${s.name}`,pad.l+i*145,30)});$('progressionSummary').textContent=`${r.name}: rainfall-driven risk is ${riskLabel} on the selected day. Hover the graph to see the exact day, state, rainfall and risk category. ${eta===null?'No High/Very High rainfall category is reached in the current outlook.':`High/Very High rainfall category first appears on Day +${eta}.`}`;}
