// Enforce the requested dashboard reading order at runtime. The sections keep their
// existing IDs/controls; only their DOM position is changed so charts, map handlers,
// and API updates continue to work without duplicating any UI.
function arrangeDashboardSections(){
  const main=document.querySelector('main');
  if(!main)return;
  const sections=[
    document.querySelector('.map-panel'),
    document.querySelector('.metrics'),
    document.querySelector('.progression'),
    document.querySelector('.details'),
    document.querySelector('.scenario-panel'),
    document.querySelector('.custom-rainfall'),
    document.querySelector('.sources')
  ].filter(Boolean);
  sections.forEach(section=>main.appendChild(section));
}
arrangeDashboardSections();
async function refreshTimeanddateWeather(){try{const [r,h]=await Promise.all([fetch('/api/timeanddate-live',{cache:'no-store'}),fetch('/api/imd-humidity',{cache:'no-store'})]);if(!r.ok)throw new Error('weather snapshot unavailable');const d=await r.json();if(h.ok){const hd=await h.json();imdHumidity=hd.humidity||{};}if(d.stateWeather&&Object.keys(d.stateWeather).length){Object.assign(stateWeather,d.stateWeather);stateForecast=d.stateForecast||{};weatherSnapshot.captured=d.checkedAt||new Date().toISOString();$('weatherStatus').textContent='Live IMD statewise rainfall + IMD relative humidity where available + Timeanddate secondary weather: '+new Date(d.checkedAt).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'});update();drawChart();runScenario(activeScenario);drawCustomPrediction();}else{$('weatherStatus').textContent='Waiting for hourly weather update';}}catch(e){$('weatherStatus').textContent='Latest hourly weather snapshot unavailable';}}
$('refreshSources').onclick=async()=>{try{const r=await fetch('/api/source-status');const d=await r.json();$('cwcStatus').textContent='CWC source reachable: '+(d.cwc?'YES':'CHECK LINK');$('googleStatus').textContent='Flood Hub reachable: '+(d.google?'YES':'CHECK LINK');}catch(e){$('cwcStatus').textContent='Open official source';$('googleStatus').textContent='Open official source';}await refreshTimeanddateWeather();};
